"""Paper 2 · Unit 7 · P2-U7-01 Software Process Models (2 × 30) and P2-U7-02 Agile Process Models (1 × 30).
References: Roger S. Pressman, Software Engineering – A Practitioner's Approach (7th/8th ed., chs. 1–6, 24–28); Ian Sommerville,
Software Engineering; Agile Manifesto (2001); Scrum Guide. Each set mixes REAL previous-year questions (exact wording, printed option
order, `source`) with new ones. Official answers: KEA final keys for Legislative Council Secretariat 2024 (Computer Operator P2,
Junior Console Operator P2 – booklet A1) and GTTC 2024 (Lecturer CS – A1, Technician Gr-III CS – C1). KSET 2023–25 questions are
reused from packs/pyq-p2.json (answers worked out by ExamSim). COCOMO, FP, risk, CPM and earned-value numbers checked by computation."""
import json
from pathlib import Path
from packlib import AR, I_II

PYQ = "PYQ pattern (KEA / KSET papers). "
KLC = " (Official answer: KEA final key, Legislative Council Secretariat exam 2024.)"
GTTC = " (Official answer: KEA final key, GTTC recruitment 2024.)"
NOTE = " (Answer worked out by ExamSim; not KEA's official key.)"

_PYQ = {q["source"]: q for s in json.loads((Path(__file__).parent.parent / "packs" / "pyq-p2.json").read_text(encoding="utf-8"))["subjects"]
        for t in s["topics"] for st in t["sets"] for q in st["questions"] if q.get("source")}


def kset(src):
    """A real KSET/KEA question already transcribed in packs/pyq-p2.json (printed option order, same answer and explanation)."""
    q = _PYQ[src]
    return (q["question"], [q["options"][k] for k in "ABCD"], "ABCD".index(q["answer"]), q["explanation"], src)


